mapper.select:
select a.id AS id, a.user_id AS userId, a.position_id AS positionId, a.level_id AS levelId, a.state AS state, a.state_name AS stateName, a.user_name AS userName, pi.position_name AS positionName, pl.level_code AS positionLevelName from user_po_level a left join position_info AS pi on a.position_id = pi.id left join position_level AS pl on a.level_id = pl.id left join user_info AS ui on a.user_id = ui.user_id where 1= 1
and a.user_name like CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')
limit #{pageIndex}, #{pageSize}

select a.* from user_po_level a
where
a.level_id = #{id,jdbcType=BIGINT}

select a.* from user_po_level a
where
a.position_id = #{id,jdbcType=BIGINT}
